  check_narm tm true false nrules iarm0_0_1RB1RC_1LB1RA_1LC0LD_0RB1LD ch_iarm0_0_1RB1RC_1LB1RA_1LC0LD_0RB1LD = true.
Proof. vm_compute. reflexivity. Qed.

