Definition mk_1RB1RC_1LC1LD_1RA0LD_0RA1LD (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB1RC_1LC1LD_1RA0LD_0RA1LD.

(** 1RB1RC_1LC1LD_1RA0LD_0RA1LD *)
Definition tm_1RB1RC_1LC1LD_1RA0LD_0RA1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DL StC
  | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S1 DR StA
  | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S0 DR StA
  | StD, S1 => mk S1 DL StD
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1RC_1LC1LD_1RA0LD_0RA1LD : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1RC_1LC1LD_1RA0LD_0RA1LD pins_1RB1RC_1LC1LD_1RA0LD_0RA1LD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1RC_1LC1LD_1RA0LD_0RA1LD : Fam := mkFam 2 [[S1;S1];[S1;S0]] [] [[];[S0;S1]] Binary 1 [mkFill 0 [] 0 [] 1;mkFill 1 [] 0 [] 0] StD S0 false [].
Local Notation FAM := fam_1RB1RC_1LC1LD_1RA0LD_0RA1LD.

(** ** The ladder, as DATA

    4 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RC_1LC1LD_1RA0LD_0RA1LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StC (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StC (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StC (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB1RC_1LC1LD_1RA0LD_0RA1LD.

Definition rules_1RB1RC_1LC1LD_1RA0LD_0RA1LD : list LRule := map fst lad.
Local Notation rules := rules_1RB1RC_1LC1LD_1RA0LD_0RA1LD.

Lemma ladder_ok_1RB1RC_1LC1LD_1RA0LD_0RA1LD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RC_1LC1LD_1RA0LD_0RA1LD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RC_1LC1LD_1RA0LD_0RA1LD. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* D[0] L<> R<1^2+y0>  ==>  D[0] L<> R<1^1 0^1 1^y0>   [4 steps] *)
Definition arm12_1RB1RC_1LC1LD_1RA0LD_0RA1LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [S1] 1 0 [])) 0 4.
Definition ch_arm12_1RB1RC_1LC1LD_1RA0LD_0RA1LD : list rstep := [RB (SWin 4)].
Lemma ok_arm12_1RB1RC_1LC1LD_1RA0LD_0RA1LD :
  check_arm tm true true rules arm12_1RB1RC_1LC1LD_1RA0LD_0RA1LD ch_arm12_1RB1RC_1LC1LD_1RA0LD_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm12_1RB1RC_1LC1LD_1RA0LD_0RA1LD : RuleSound tm true true arm12_1RB1RC_1LC1LD_1RA0LD_0RA1LD.
Proof. eapply arm_sound; [exact rules_sound_1RB1RC_1LC1LD_1RA0LD_0RA1LD | exact ok_arm12_1RB1RC_1LC1LD_1RA0LD_0RA1LD]. Qed.

