          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1;S1] 1 0 [S0;S1])) 0 1.
Definition ch_farm1_0_1RB1RC_1LC1LD_1RA0LD_0RA1LD : list nseg :=
  [NCh [RB (SWin 2);RB (SCycR 2);RB (SWinR 4);RB (SCycL 2 0);RB (SWin 2)]].
Lemma ok_farm1_0_1RB1RC_1LC1LD_1RA0LD_0RA1LD :
