    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RD_0LC1LB_0RD1LC_1RA0RB : list (LRule * list rstep) :=
  [(mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StA (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB1RD_0LC1LB_0RD1LC_1RA0RB.

Definition rules_1RB1RD_0LC1LB_0RD1LC_1RA0RB : list LRule := map fst lad.
Local Notation rules := rules_1RB1RD_0LC1LB_0RD1LC_1RA0RB.

Lemma ladder_ok_1RB1RD_0LC1LB_0RD1LC_1RA0RB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RD_0LC1LB_0RD1LC_1RA0RB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RD_0LC1LB_0RD1LC_1RA0RB. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
