          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1;S1;S1;S1] [S1;S1] 1 0 [S1;S1;S0])) 4 18.
Definition ch_arm7_1RB1RD_0LC1LB_0RD1LC_1RA0RB : list rstep := [RB (SWin 6);RB (SCycR 2);RB (SWinR 6);RB (SCycL 2 0);RB (SWin 6)].
