(* arm11: NO KERNEL CHAIN -- no chain found *)
(* arm12: NO KERNEL CHAIN -- no chain found *)
(* arm39: NO KERNEL CHAIN -- no chain found *)
(* arm23: NO KERNEL CHAIN -- no chain found *)
(* arm33: NO KERNEL CHAIN -- no chain found *)
(* arm38: NO KERNEL CHAIN -- no chain found *)
(* arm9: NO KERNEL CHAIN -- no chain found *)
(** ** What this board establishes

    4 of 11 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 11 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    0 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB1RD_0LC1LB_0RD1LC_1RA0RB : list (LRule * list rstep) :=
  [].
Definition nrules_1RB1RD_0LC1LB_0RD1LC_1RA0RB : list LRule := map fst nlad_1RB1RD_0LC1LB_0RD1LC_1RA0RB.
Local Notation nrules := nrules_1RB1RD_0LC1LB_0RD1LC_1RA0RB.

Lemma nladder_ok_1RB1RD_0LC1LB_0RD1LC_1RA0RB : check_ladder tm [] nlad_1RB1RD_0LC1LB_0RD1LC_1RA0RB = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1RD_0LC1LB_0RD1LC_1RA0RB : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1RD_0LC1LB_0RD1LC_1RA0RB. Qed.

Definition iarm0_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB : list nseg :=
  [NCh [RB (SWin 4)]].
Lemma ok_iarm0_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB :
  check_narm tm true false nrules iarm0_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB ch_iarm0_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB1RD_0LC1LB_0RD1LC_1RA0RB : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 [S1;S1]))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1;S1] 1 0 [S0;S1])) 0 1.
Definition ch_iarm0_1_1RB1RD_0LC1LB_0RD1LC_1RA0RB : list nseg :=
  [NCh [RB (SWin 2);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 2)]].
Lemma ok_iarm0_1_1RB1RD_0LC1LB_0RD1LC_1RA0RB :
  check_narm tm true false nrules iarm0_1_1RB1RD_0LC1LB_0RD1LC_1RA0RB ch_iarm0_1_1RB1RD_0LC1LB_0RD1LC_1RA0RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1;S1] 1 0 [S1;S1])) 0 1.
Definition ch_farm1_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB : list nseg :=
  [NCh [RB (SWin 2);RB (SCycR 2);RB (SWinR 6);RB (SCycL 2 0);RB (SWin 2)]].
Lemma ok_farm1_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB :
  check_narm tm true true nrules farm1_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB ch_farm1_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1RD_0LC1LB_0RD1LC_1RA0RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB
  | 0, 1 => iarm0_1_1RB1RD_0LC1LB_0RD1LC_1RA0RB
  | _, _ => iarm0_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1RD_0LC1LB_0RD1LC_1RA0RB (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB
  | _, _ => farm1_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RD_0LC1LB_0RD1LC_1RA0RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1RD_0LC1LB_0RD1LC_1RA0RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB1RD_0LC1LB_0RD1LC_1RA0RB (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 2;SCycR 2;SWinR 2]
  | 1, (StA, S1) => [SWin 2]
  | 1, (StB, S0) => [SWin 2;SCycR 2;SWinR 3]
  | 1, (StB, S1) => [SWin 2;SCycR 2;SWinR 6;SCycL 2 0;SWin 4]
  | 1, (StC, S0) => [SWin 0]
  | 1, (StC, S1) => [SWin 2;SCycR 2;SWinR 4]
  | 1, (StD, S0) => [SWin 1]
  | 1, (StD, S1) => [SWin 2;SCycR 2;SWinR 6;SCycL 2 0;SWin 3]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB1RD_0LC1LB_0RD1LC_1RA0RB (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | _, _ => []
  end.

Lemma iarm_reach_1RB1RD_0LC1LB_0RD1LC_1RA0RB : forall d r,
  d < fm_b FAM - 1 -> r < 1 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_1RB1RD_0LC1LB_0RD1LC_1RA0RB d r)) (lr_rhs (iarm_1RB1RD_0LC1LB_0RD1LC_1RA0RB d r)).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1RD_0LC1LB_0RD1LC_1RA0RB | exact ok_iarm0_0_1RB1RD_0LC1LB_0RD1LC_1RA0RB]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1RD_0LC1LB_0RD1LC_1RA0RB | exact ok_iarm0_1_1RB1RD_0LC1LB_0RD1LC_1RA0RB]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

