Lemma bootl_1RB1RD_0LC1LB_0RD1LC_1RA0RB :
  stepn tm 12 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 12 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 12 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1RD_0LC1LB_0RD1LC_1RA0RB : NeverQuasiHaltsTr tm_1RB1RD_0LC1LB_0RD1LC_1RA0RB.
Proof.
  eapply (boardN_neverqhtr tm_1RB1RD_0LC1LB_0RD1LC_1RA0RB pins_1RB1RD_0LC1LB_0RD1LC_1RA0RB FAM 1
                           iarm_1RB1RD_0LC1LB_0RD1LC_1RA0RB 1 1
                           farm_1RB1RD_0LC1LB_0RD1LC_1RA0RB 1 1
                           fm1_1RB1RD_0LC1LB_0RD1LC_1RA0RB fm2_1RB1RD_0LC1LB_0RD1LC_1RA0RB 0
                           nrules vsegs_1RB1RD_0LC1LB_0RD1LC_1RA0RB vis_1RB1RD_0LC1LB_0RD1LC_1RA0RB
                           [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1RD_0LC1LB_0RD1LC_1RA0RB.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
