Lemma fm12_1RB1RD_1LC0RD_1LA1LB_0LB1RA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 4 ->
  fm1_1RB1RD_1LC0RD_1LA1LB_0LB1RA r ph + fm2_1RB1RD_1LC0RD_1LA1LB_0LB1RA r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
  = r + f_s (fam_fill FAM ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
